CREATE TYPE "seat_type" AS ENUM (
	'premium',
	'super_premium',
	'regular',
	'double'
);

CREATE TYPE "ticket_type" AS ENUM (
	'regular',
	'student',
	'discount'
);

CREATE TYPE "genre" AS ENUM (
	'animation',
	'action',
	'comedy ',
	'drama ',
	'horror ',
	'science ',
	'fiction ',
	'romance',
	'thriller ',
	'fantasy',
	'mystery ',
	'western ',
	'animation ',
	'documentary'
);

CREATE TABLE IF NOT EXISTS "movies" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"session_id" INTEGER NOT NULL,
	"genre" GENRE NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "users" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"first_name" VARCHAR(255) NOT NULL,
	"last_name" VARCHAR(255) NOT NULL,
	"email" VARCHAR(255) NOT NULL,
	"phone" VARCHAR(20) NOT NULL,
	"ticket" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "cinema_locations" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"address" VARCHAR(255) NOT NULL,
	"hall_count" INTEGER NOT NULL,
	"is_active" BOOLEAN NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "cinema_halls" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"row_count" INTEGER NOT NULL,
	"seat_count" INTEGER NOT NULL,
	"location_id" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "sessions" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"location_id" INTEGER NOT NULL,
	"start_time" TIME NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "tickets" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"session_id" INTEGER NOT NULL,
	"user_id" INTEGER NOT NULL,
	"hall" VARCHAR(255) NOT NULL,
	"ticket_type" TICKET_TYPE NOT NULL,
	"seat" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "seats" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"row" INTEGER NOT NULL,
	"seat_type" SEAT_TYPE NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "reviews" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"user_id" INTEGER NOT NULL,
	"date" DATE NOT NULL,
	"time" TIME,
	"comment" JSON,
	"stars" SMALLINT,
	PRIMARY KEY("id")
);

ALTER TABLE "tickets"
ADD FOREIGN KEY("id") REFERENCES "users"("ticket")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "tickets"
ADD FOREIGN KEY("hall") REFERENCES "cinema_halls"("name")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "movies"
ADD FOREIGN KEY("session_id") REFERENCES "sessions"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "sessions"
ADD FOREIGN KEY("location_id") REFERENCES "cinema_locations"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "tickets"
ADD FOREIGN KEY("session_id") REFERENCES "sessions"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "tickets"
ADD FOREIGN KEY("seat") REFERENCES "seats"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "cinema_halls"
ADD FOREIGN KEY("location_id") REFERENCES "cinema_locations"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "reviews"
ADD FOREIGN KEY("id") REFERENCES "users"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;